record.field:
model_name = params.get('model', '').strip()
if not model_name or model_name not in env:
    result = {'success': False, 'error': f'Model "{model_name}" not found.'}
else:
    EXCLUDED = {
        'id', 'create_date', 'write_date', 'create_uid', 'write_uid',
        'message_ids', 'message_follower_ids', 'message_partner_ids',
        'activity_ids', 'website_message_ids', 'activity_state',
        'activity_summary', '__last_update',
    }
    ALLOWED_TYPES = {'char', 'text', 'integer', 'float', 'monetary', 'boolean',
                     'selection', 'date', 'datetime'}

    all_fields = env[model_name].fields_get(
        attributes=['string', 'type', 'required', 'readonly', 'help', 'selection']
    )
    schema = {}
    for fname, finfo in all_fields.items():
        if fname in EXCLUDED or fname.startswith('_'):
            continue
        if finfo.get('readonly'):
            continue
        if finfo['type'] not in ALLOWED_TYPES:
            continue
        entry = {'label': finfo['string'], 'type': finfo['type']}
        if finfo.get('required'):
            entry['required'] = True
        if finfo.get('help'):
            entry['help'] = finfo['help']
        if finfo['type'] == 'selection':
            entry['options'] = {k: v for k, v in (finfo.get('selection') or [])}
        schema[fname] = entry

    result = {'success': True, 'model': model_name, 'fields': schema}
